import sympy
from sympy import Poly
import math
import functools

x, y, z = sympy.symbols('x y z')

CONDITION_LABELS = [
    "H_1: R is a commutative ring with identity",
    "H_2: f and g are polynomials over R",
    "H_3: c(h) denotes the ideal generated by the coefficients of a polynomial h",
    "¬Q: The content ideal c(fg) is not equal to the content ideal c(g)"
]

N_HYP = 3
NEG_Q_INDEX = 3

def conditions(witness):
    try:
        if isinstance(witness, tuple):
            if len(witness) == 3:
                f, g, var = witness
            elif len(witness) == 2:
                f, g = witness
                free = (sympy.sympify(f).free_symbols | sympy.sympify(g).free_symbols)
                if free:
                    if x in free:
                        var = x
                    else:
                        var = list(free)[0]
                else:
                    var = x
            else:
                return [False, False, False, False]
        else:
            return [False, False, False, False]
    except Exception:
        return [False, False, False, False]

    try:
        f_expr = f.as_expr() if isinstance(f, Poly) else sympy.sympify(f)
        g_expr = g.as_expr() if isinstance(g, Poly) else sympy.sympify(g)
        f_poly = Poly(f_expr, var)
        g_poly = Poly(g_expr, var)
        h1 = True
    except Exception:
        h1 = False

    try:
        if h1:
            _ = f_poly.coeffs()
            _ = g_poly.coeffs()
            h2 = True
        else:
            h2 = False
    except Exception:
        h2 = False

    h3 = h2

    try:
        fg_poly = Poly(f_expr * g_expr, var)
        C_fg = fg_poly.coeffs()
        C_g = g_poly.coeffs()
        
        free_vars = set()
        for c in C_fg + C_g:
            free_vars.update(c.free_symbols)
        
        def ideals_equal(C1, C2, free_vars):
            try:
                ints1 = []
                for c in C1:
                    if isinstance(c, int):
                        ints1.append(c)
                    elif hasattr(c, 'is_Integer') and c.is_Integer:
                        ints1.append(int(c))
                    else:
                        raise TypeError
                ints2 = []
                for c in C2:
                    if isinstance(c, int):
                        ints2.append(c)
                    elif hasattr(c, 'is_Integer') and c.is_Integer:
                        ints2.append(int(c))
                    else:
                        raise TypeError
                        
                g1 = functools.reduce(math.gcd, ints1) if ints1 else 0
                g2 = functools.reduce(math.gcd, ints2) if ints2 else 0
                return abs(g1) == abs(g2)
            except TypeError:
                pass
            
            vars_list = list(free_vars)
            if not vars_list:
                is_zero1 = all(c == 0 for c in C1)
                is_zero2 = all(c == 0 for c in C2)
                return is_zero1 == is_zero2
            
            gb1 = sympy.groebner(C1, *vars_list, domain='QQ')
            gb2 = sympy.groebner(C2, *vars_list, domain='QQ')
            
            for c in C1:
                _, rem = sympy.reduced(c, gb2, *vars_list, domain='QQ')
                if rem != 0: return False
            for c in C2:
                _, rem = sympy.reduced(c, gb1, *vars_list, domain='QQ')
                if rem != 0: return False
                
            if len(C1) == 1 and len(C2) == 1:
                ratio = sympy.simplify(C1[0] / C2[0])
                if not (ratio == 1 or ratio == -1):
                    return False
                    
            return True

        eq = ideals_equal(C_fg, C_g, free_vars)
        neg_q = not eq
    except Exception:
        neg_q = False

    return [h1, h2, h3, neg_q]